from attr import attrs, validators
from attr.validators import disabled

@attrs
class C:
    x = validators.instance_of(int)

try:
    with disabled():
        C(x="not_int")
        print("Success: validator is disabled")
except TypeError as e:
    print(f"Failure: validator ran with error: {e}")
    import sys
    sys.exit(1)

from attr import attrs, ib, validators
from attr.validators import disabled

@attrs
class C:
    x = ib(validator=validators.instance_of(int))

try:
    with disabled():
        C(x="not_int")
        print("Success: validator is disabled")
except TypeError as e:
    print(f"Failure: validator ran with error: {e}")
    import sys
    sys.exit(1)
